  for (const f of ["email", "firstname", "lastname", "jobtitle", "company", "mobilephone",
                    "seniority", "city", "state", "country", "hs_state_code",
                    "hs_country_region_code", "lv_persona_group"]) {
    if (row[f] != null && String(row[f]).trim() !== "") candidate[f] = row[f];
  }
  if (row.linkedin_url != null && String(row.linkedin_url).trim() !== "") {
    // D-72-04: land BOTH the canonical field (PN-1) and the native portal property
    // from the same value — one canonicalization, two write targets, one map.
    for (const target of CANDIDATE_ALIASES.linkedin_url) candidate[target] = row.linkedin_url;
  }
  if (row.phone_normalized) candidate.phone = row.phone_normalized;
  // Phase 72 Plan 04 (D-72-07): stamped by "Adapt Contact History" on a matched row
  // only -- a net_new/unmatched row degrades to {}, which is the pre-72 "unknown
  // freshness" outcome for every stale_refreshable field, exactly as designed.
  const merged = mergeContacts(row.existingRecord || {}, candidate, undefined,
    { source: "csv", confidence: 80, confidenceByField, sourceByField,
      historyByField: row.historyByField || {} });
  return { json: { ...row, merge: merged } };
});

// Decide Action (dry-run echo) — LOCAL variant.
// Replaces the HubSpot update/create write nodes: ECHOES the would-be payload,
// performs NO real write. `create` stays gated behind allow_create (default false).
// Phase 15: this is the SINGLE serialization point for the provenance blob — the
// stamper (mergeContacts.js) returns the parsed provenance object, never a string.
function _sortedForStringify(v) {
